{"command":"cat > gcmtest2.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* OpenSSL internal. Signature from crypto/modes/gcm128.c usage:
   void aesni_gcm_encrypt(const unsigned char *in, unsigned char *out,
                          size_t len, const void *key, unsigned char ivec[16],
                          u64 *Xi);  ? Let's probe by checking nm and known layout.
   Known signature (OpenSSL crypto/aes/asm/aesni-x86_64.pl):
   void aesni_gcm_encrypt(const void *inp, void *out, size_t len,
                          const void *key, unsigned char iv[16], void *Xi)
   Actually the perl asm says:
     aesni_gcm_encrypt(in, out, len, key, ivec, Xi)
   where ivec is 16 bytes counter block and Xi is the GHASH state (16 bytes).
*/

extern void aesni_gcm_encrypt(const unsigned char *in, unsigned char *out,
                              size_t len, const void *key,
                              unsigned char ivec[16], unsigned char Xi[16]);

int main() {
    unsigned char keyb[16], iv[12], *pt, *ct, tag[16], aad[32];
    size_t n = 61440000;
    for (int i=0;i<16;i++) keyb[i]=i+1;
    for (int i=0;i<12;i++) iv[i]=i;
    for (int i=0;i<32;i++) aad[i]=i;
    pt = malloc(n); ct = malloc(n+16);
    memset(pt, 0x42, n);

    AES_KEY aes;
    AES_set_encrypt_key(keyb, 128, &aes);

    // reference via ctr32 path
    unsigned char *ref = malloc(n);
    unsigned char reftag[16];
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&aes, (block128_f)AES_encrypt);
    extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out, size_t blocks, const void *key, const unsigned char ivec[16]);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_aad(ctx, aad, 32);
    CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ref, n, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, reftag, 16);
    printf("ref tag: "); for(int i=0;i<16;i++) printf("%02x", reftag[i]); printf("\n");

    // Try aesni_gcm_encrypt. We need the AESNI key schedule format, not AES_KEY.
    // aesni_set_encrypt_key(userKey, bits, key_schedule)
    // key schedule for aesni is 16*(rounds+1) bytes = 176 for aes128, but aligned 16 and
    // the rounds count is stored after. Let's allocate generously and try.
    unsigned char ks[16*15+64];
    memset(ks, 0, sizeof(ks));
    extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
    int r = aesni_set_encrypt_key(keyb, 128, ks);
    printf("aesni_set_encrypt_key -> %d\n", r);

    // Build ivec: iv || 00 00 00 02 (counter starts at 2 for the data, counter 1 is for tag)
    unsigned char ivec[16];
    memset(ivec, 0, 16);
    memcpy(ivec, iv, 12);
    ivec[15] = 2;

    // Xi must be pre-computed GHASH state. For a probe, zero it and see speed only.
    unsigned char Xi[16];
    memset(Xi, 0, 16);

    // speed only, small first to check crash
    size_t sn = 1024;
    unsigned char spt[1024], sct[1024];
    memset(spt, 0x42, sn);
    aesni_gcm_encrypt(spt, sct, sn, ks, ivec, Xi);
    printf("small call ok, first bytes %02x %02x\n", sct[0], sct[1]);

    for (int i=0;i<3;i++) {
        memset(ivec,0,16); memcpy(ivec, iv, 12); ivec[15]=2;
        memset(Xi, 0, 16);
        double t0 = now();
        aesni_gcm_encrypt(pt, ct, n, ks, ivec, Xi);
        double dt = now()-t0;
        printf("aesni_gcm %d: %.4fs %.0f MB/s first %02x%02x\n", i, dt, n/dt/1e6, ct[0], ct[1]);
    }
    printf("ctr32 first %02x%02x\n", ref[0], ref[1]);
    return 0;
}
EOF
