{"command":"export TMPDIR=$PWD/tmp && cat > bench.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out, size_t blocks, const void *key, const unsigned char ivec[16]);
extern void gcm_init_clmul(unsigned char Htable[16*16], const unsigned char H[16]);
extern void gcm_ghash_clmul(unsigned char Xi[16], const unsigned char Htable[16*16], const unsigned char *inp, size_t len);

static void gcm_full(const AES_KEY *aes, const unsigned char iv[12],
                     const unsigned char *aad, size_t aadlen,
                     const unsigned char *in, unsigned char *out, size_t len,
                     unsigned char tag[16]) {
    /* Use OpenSSL's own CRYPTO_gcm128 which selects the asm path internally when
       given the ctr32 stream function. */
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new((void*)aes, (block128_f)AES_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    if (aadlen) CRYPTO_gcm128_aad(ctx, aad, aadlen);
    CRYPTO_gcm128_encrypt_ctr32(ctx, in, out, len, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, tag, 16);
    CRYPTO_gcm128_release(ctx);
}

int main(){
    size_t n = 61440000;
    unsigned char *pt = malloc(n), *ct = malloc(n), key[16], iv[12], aad[32], tag[16];
    memset(pt, 0x42, n);
    for(int i=0;i<16;i++) key[i]=i+1;
    for(int i=0;i<12;i++) iv[i]=i;
    for(int i=0;i<32;i++) aad[i]=i;
    AES_KEY aes; AES_set_encrypt_key(key, 128, &aes);

    /* per-call context allocation */
    for(int i=0;i<3;i++){
        double t0=now();
        gcm_full(&aes, iv, aad, 32, pt, ct, n, tag);
        double dt=now()-t0;
        printf("new ctx each call %d: %.4fs %.0f MB/s\n", i, dt, n/dt/1e6);
    }
    /* reused context */
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&aes, (block128_f)AES_encrypt);
    for(int i=0;i<4;i++){
        double t0=now();
        CRYPTO_gcm128_setiv(ctx, iv, 12);
        CRYPTO_gcm128_aad(ctx, aad, 32);
        CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ct, n, aesni_ctr32_encrypt_blocks);
        CRYPTO_gcm128_tag(ctx, tag, 16);
        double dt=now()-t0;
        printf("reused ctx %d: %.4fs %.0f MB/s\n", i, dt, n/dt/1e6);
    }

    /* split: ctr then ghash, to see individual costs */
    unsigned char H[16], Htable[16*16], Xi[16];
    memset(H,0,16);
    AES_encrypt(H, H, &aes);            /* H = AES(0) */
    gcm_init_clmul(Htable, H);
    unsigned char ivec[16];
    for(int i=0;i<3;i++){
        double t0=now();
        memset(ivec,0,16); memcpy(ivec, iv, 12); ivec[15]=2;
        aesni_ctr32_encrypt_blocks(pt, ct, n/16, &aes, ivec);
        double dt=now()-t0;
        printf("ctr only %d: %.4fs %.0f MB/s\n", i, dt, n/dt/1e6);
    }
    for(int i=0;i<3;i++){
        memset(Xi,0,16);
        double t0=now();
        gcm_ghash_clmul(Xi, Htable, ct, n);
        double dt=now()-t0;
        printf("ghash only %d: %.4fs %.0f MB/s\n", i, dt, n/dt/1e6);
    }
    printf("done\n");
    return 0;
}
EOF
