#include <openssl/modes.h>
extern void aesni_ctr32_encrypt_blocks(const unsigned char*, unsigned char*, size_t, const void*, const unsigned char[16]);
static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}
typedef struct { const AES_KEY *aes; unsigned char *pt; unsigned char *ct; size_t n; unsigned char iv[16]; pthread_barrier_t *b; } job;
void *work(void *arg){
    job *j = arg;
    pthread_barrier_wait(j->b);
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new((void*)j->aes, (block128_f)AES_encrypt);
    unsigned char iv[12]; memcpy(iv, j->iv, 12);
    unsigned char tag[16];
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_encrypt_ctr32(ctx, j->pt, j->ct, j->n, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, tag, 16);
    CRYPTO_gcm128_release(ctx);
    return NULL;
}
int main(){
    size_t total = 61440000;
    int counts[] = {1,2,4,6,8};
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i;
    AES_KEY aes; AES_set_encrypt_key(key,128,&aes);
    for (int c=0;c<5;c++){
        int nt = counts[c];
        size_t chunk = total/nt;
        pthread_t th[16]; job jobs[16]; pthread_barrier_t b;
        pthread_barrier_init(&b, NULL, nt);
        for(int i=0;i<nt;i++){
            jobs[i].aes=&aes; jobs[i].n=chunk; jobs[i].b=&b;
            jobs[i].pt=malloc(chunk); jobs[i].ct=malloc(chunk);
            memset(jobs[i].pt, 0x42, chunk);
            memset(jobs[i].iv, 0, 16); jobs[i].iv[0]=i;
        }
        for(int trial=0;trial<3;trial++){
            double t0=now();
            for(int i=0;i<nt;i++) pthread_create(&th[i], NULL, work, &jobs[i]);
            for(int i=0;i<nt;i++) pthread_join(th[i], NULL);
            double dt=now()-t0;
            printf("%d thr trial %d: %.4fs %.0f MB/s\n", nt, trial, dt, total/dt/1e6);
        }
        pthread_barrier_destroy(&b);
        for(int i=0;i<nt;i++){free(jobs[i].pt);free(jobs[i].ct);}
    }
    return 0;
}
