#include <openssl/aes.h>
#include <openssl/modes.h>
extern void aesni_ctr32_encrypt_blocks(const unsigned char*, unsigned char*, size_t, const void*, const unsigned char[16]);
extern void gcm_init_clmul(unsigned char Htable[16*16], const unsigned char H[16]);
extern void gcm_ghash_clmul(unsigned char Xi[16], const unsigned char Htable[16*16], const unsigned char *inp, size_t len);
extern void gcm_gmult_clmul(unsigned char Xi[16], const unsigned char Htable[16*16]);

static void bswap16(unsigned char *x){
    for(int i=0;i<8;i++){ unsigned char t=x[i]; x[i]=x[15-i]; x[15-i]=t; }
}
static void xor16(unsigned char *a, const unsigned char *b){ for(int i=0;i<16;i++) a[i]^=b[i]; }

/* GHASH over a buffer that may not be 16-aligned in length, with bit lengths */
static void ghash_blocks(unsigned char Xi[16], const unsigned char *Htable, const unsigned char *p, size_t len){
    size_t full = len & ~15u;
    if (full) gcm_ghash_clmul(Xi, Htable, p, full);
    if (len & 15){
        unsigned char last[16]; memset(last,0,16); memcpy(last, p+full, len&15);
        gcm_ghash_clmul(Xi, Htable, last, 16);
    }
}

int main(){
    unsigned char key[16], iv[12], aad[32], tag_ref[16], tag[16];
    size_t n = 100000; /* not multiple of 16 */
    for(int i=0;i<16;i++) key[i]=i+1;
    for(int i=0;i<12;i++) iv[i]=i*3;
    for(int i=0;i<32;i++) aad[i]=i*5;
    unsigned char *pt=malloc(n), *ct=malloc(n+16), *ref=malloc(n);
    for(size_t i=0;i<n;i++) pt[i]=i*7;

    AES_KEY aes; AES_set_encrypt_key(key,128,&aes);
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&aes,(block128_f)AES_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_aad(ctx, aad, 32);
    CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ref, n, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, tag_ref, 16);

