    unsigned char H[16]; memset(H,0,16); AES_encrypt(H,H,&aes);
    unsigned char Htable[16*16];
    gcm_init_clmul(Htable, H);

    /* CTR: J0 = iv || 0x00000001 ; data counter starts at inc32(J0) = ...0002 */
    unsigned char J0[16]; memset(J0,0,16); memcpy(J0, iv, 12); J0[15]=1;
    unsigned char ctr[16]; memcpy(ctr, J0, 16);
