    for(int i=15;i>=12;i--){ if(++ctr[i]) break; }
    size_t full = n/16;
    aesni_ctr32_encrypt_blocks(pt, ct, full, &aes, ctr);
    if (n & 15){
        unsigned char stream[16], tmp[16]; memset(tmp,0,16);
        AES_encrypt(ctr, stream, &aes);
        for(size_t i=0;i<(n&15);i++) ct[full*16+i] = pt[full*16+i]^stream[i];
    }
    int ctmatch = memcmp(ct, ref, n)==0;
    printf("ciphertext match: %d\n", ctmatch);
    if(!ctmatch){ printf("ref %02x%02x ct %02x%02x\n", ref[0],ref[1],ct[0],ct[1]); }

    /* GHASH: AAD then ciphertext then lengths. Xi in the byte order gcm_ghash expects.
       OpenSSL's gcm_ghash_clmul operates on the internal byte-swapped Xi. Let's just
       compare by computing GHASH the way CRYPTO_gcm128 does: feed aad and ct. */
    unsigned char Xi[16]; memset(Xi,0,16);
    ghash_blocks(Xi, Htable, aad, 32);
    ghash_blocks(Xi, Htable, ct, n);
    unsigned char lenblock[16]; memset(lenblock,0,16);
    uint64_t alen = 32ull*8, clen = (uint64_t)n*8;
    for(int i=0;i<8;i++){ lenblock[7-i]=alen>>(8*i); lenblock[15-i]=clen>>(8*i); }
    gcm_ghash_clmul(Xi, Htable, lenblock, 16);
