    unsigned char S[16]; AES_encrypt(J0, S, &aes);
    unsigned char tag1[16], tag2[16];
    for(int i=0;i<16;i++){ tag1[i]=Xi[i]^S[i]; tag2[i]=Xi[15-i]^S[i]; }
    printf("tag ref : "); for(int i=0;i<16;i++) printf("%02x", tag_ref[i]); printf("\n");
    printf("tag raw : "); for(int i=0;i<16;i++) printf("%02x", tag1[i]); printf("\n");
    printf("tag swap: "); for(int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");
    printf("Xi      : "); for(int i=0;i<16;i++) printf("%02x", Xi[i]); printf("\n");
