#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>
#include <openssl/aes.h>
extern void aesni_ctr32_encrypt_blocks(const unsigned char*, unsigned char*, size_t, const void*, const unsigned char[16]);
extern void aesni_encrypt(const unsigned char*, unsigned char*, const void*);
extern int aesni_set_encrypt_key(const unsigned char*, int, void*);
extern void gcm_init_clmul(unsigned char*, const unsigned char*);
extern void gcm_ghash_clmul(unsigned char*, const unsigned char*, const unsigned char*, size_t);
static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}
static atomic_int go_flag;

#define SEG (1<<20)  /* 1 MB segments */

typedef struct {
    unsigned char *ks, *Htable, *pt, *ct;
    size_t n;
    unsigned char ctr0[16];
    int role; /* 0 = ctr producer, 1 = ghash consumer, for pipelined pair */
    atomic_int *produced; /* segments completed by ctr */
    int id;
} job;

void *pipe_work(void *arg){
    job *j = arg;
    while (atomic_load(&go_flag)==0);
    size_t segs = j->n / SEG;
    if (j->role==0){
        unsigned char ctr[16]; memcpy(ctr, j->ctr0, 16);
        for(size_t s=0;s<segs;s++){
            aesni_ctr32_encrypt_blocks(j->pt+s*SEG, j->ct+s*SEG, SEG/16, j->ks, ctr);
            atomic_store(j->produced+s, 1);
        }
    } else {
        unsigned char Xi[16]; memset(Xi,0,16);
        for(size_t s=0;s<segs;s++){
            while(atomic_load(j->produced+s)==0);
            gcm_ghash_clmul(Xi, j->Htable, j->ct+s*SEG, SEG);
        }
    }
    return NULL;
}

int main(){
    size_t total = (61440000/SEG)*SEG;
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i;
    unsigned char ks[256]; memset(ks,0,sizeof ks); aesni_set_encrypt_key(key,128,ks);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,ks);
    for(int k=0;k<2;k++){unsigned char*p=H+8*k;for(int i=0;i<4;i++){unsigned char t=p[i];p[i]=p[7-i];p[7-i]=t;}}
    unsigned char Htable[256]; gcm_init_clmul(Htable,H);

    int pairs_list[]={1,2,3,4};
    for(int pi=0;pi<4;pi++){
        int pairs=pairs_list[pi];
        size_t chunk=(total/pairs)/SEG*SEG;
        int nsegs = chunk/SEG;
        pthread_t th[16]; job jobs[16];
        atomic_int *flags[8];
        unsigned char *pts[8], *cts[8];
        for(int i=0;i<pairs;i++){
            flags[i]=calloc(nsegs, sizeof(atomic_int));
            pts[i]=malloc(chunk); cts[i]=malloc(chunk); memset(pts[i],0x42,chunk);
            for(int r=0;r<2;r++){
                job *j=&jobs[2*i+r];
                j->ks=ks; j->Htable=Htable; j->pt=pts[i]; j->ct=cts[i]; j->n=chunk;
                j->role=r; j->produced=flags[i];
                memset(j->ctr0,0,16); j->ctr0[15]=2;
            }
        }
        for(int trial=0;trial<3;trial++){
            for(int i=0;i<pairs;i++) for(int s=0;s<nsegs;s++) atomic_store(&flags[i][s],0);
            atomic_store(&go_flag,0);
            int nt=pairs*2;
            for(int i=0;i<nt;i++) pthread_create(&th[i],NULL,pipe_work,&jobs[i]);
            struct timespec ts={0,3000000}; nanosleep(&ts,NULL);
            double t0=now(); atomic_store(&go_flag,1);
            for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
            double dt=now()-t0;
            printf("%d pairs trial %d: %.4fs %.0f MB/s\n", pairs, trial, dt, (chunk*pairs)/dt/1e6);
        }
        for(int i=0;i<pairs;i++){free(flags[i]);free(pts[i]);free(cts[i]);}
    }
    return 0;
}
