static PyObject *py_encrypt(PyObject *self, PyObject *args){
    Py_buffer key, iv, aad, pt;
    memset(&aad, 0, sizeof aad);
    if (!PyArg_ParseTuple(args, "y*y*s*y*", &key, &iv, &pt, &aad)) return NULL;
    int bits = (int)key.len * 8;
    if (bits != 128 && bits != 192 && bits != 256){
        PyBuffer_Release(&key); PyBuffer_Release(&iv); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key size"); return NULL;
    }
    unsigned char ks[256];
    memset(ks, 0, sizeof ks);
    if (aesni_set_encrypt_key(key.buf, bits, ks) != 0){
        PyBuffer_Release(&key); PyBuffer_Release(&iv); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "key setup failed"); return NULL;
    }
    PyObject *ctobj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tagobj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ctobj || !tagobj){ Py_XDECREF(ctobj); Py_XDECREF(tagobj);
        PyBuffer_Release(&key); PyBuffer_Release(&iv); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return PyErr_NoMemory(); }

    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(ks, (block128_f)aesni_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv.buf, iv.len);
    if (aad.len) CRYPTO_gcm128_aad(ctx, aad.buf, aad.len);
    CRYPTO_gcm128_encrypt_ctr32(ctx, pt.buf, (unsigned char*)PyBytes_AS_STRING(ctobj), pt.len, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, (unsigned char*)PyBytes_AS_STRING(tagobj), 16);
    CRYPTO_gcm128_release(ctx);

    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, ctobj);
    PyTuple_SET_ITEM(res, 1, tagobj);
    PyBuffer_Release(&key); PyBuffer_Release(&iv); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    return res;
}
